const path = require('path');
const { Pool } = require('pg');

const app = express();
const port = Number(process.env.APPLICATION_PORT || 8000);
const pool = new Pool({ connectionString: process.env.POSTGRES_DATABASE_URL });

app.disable('x-powered-by');
app.use(express.json({ limit: '1mb' }));
app.use(express.static(path.join(__dirname, 'public')));

function toNote(row) {
  return {
    id: row.id,
    body: row.body,
    updatedAt: row.updated_at.toISOString(),
  };
}

app.get('/api/notes', async (req, res, next) => {
  try {
    const result = await pool.query('select id, body, updated_at from notes order by updated_at desc, id desc');
    res.json(result.rows.map(toNote));
  } catch (error) {
    next(error);
  }
});

app.post('/api/notes', async (req, res, next) => {
  try {
    const result = await pool.query('insert into notes (body, updated_at) values ($1, now()) returning id, body, updated_at', ['']);
    res.status(201).json(toNote(result.rows[0]));
  } catch (error) {
    next(error);
  }
});

app.get('/api/notes/:id', async (req, res, next) => {
  try {
    const result = await pool.query('select id, body, updated_at from notes where id = $1', [req.params.id]);
    if (!result.rowCount) {
      res.status(404).json({ error: 'Note not found' });
      return;
    }
    res.json(toNote(result.rows[0]));
  } catch (error) {
    next(error);
  }
});

app.put('/api/notes/:id', async (req, res, next) => {
  try {
    const body = typeof req.body.body === 'string' ? req.body.body : '';
    const result = await pool.query('update notes set body = $1, updated_at = now() where id = $2 returning id, body, updated_at', [body, req.params.id]);
    if (!result.rowCount) {
      res.status(404).json({ error: 'Note not found' });
      return;
    }
    res.json(toNote(result.rows[0]));
  } catch (error) {
    next(error);
  }
});

app.delete('/api/notes/:id', async (req, res, next) => {
  try {
    const result = await pool.query('delete from notes where id = $1', [req.params.id]);
    if (!result.rowCount) {
      res.status(404).json({ error: 'Note not found' });
      return;
    }
    res.status(204).end();
  } catch (error) {
    next(error);
  }
});

app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.use((error, req, res, next) => {
  console.error(error);
  res.status(500).json({ error: 'Server error' });
});

app.listen(port, '0.0.0.0', () => {
  console.log(`Notes app listening on port ${port}`);
});
"}

