{"filePath": "/app/public/app.js", "content": "const PASSWORD = 'my-notes-are-mine';
const state = {
  unlocked: false,
  notes: [],
  currentNote: null,
  draft: '',
  error: '',
  query: '',
  saving: false,
};

const app = document.getElementById('app');

function titleFor(body) {
  const line = body.split('\n').find((item) => item.trim());
  return line ? line.trim() : 'New Note';
}

function previewFor(body) {
  const lines = body.split('\n');
  const titleIndex = lines.findIndex((item) => item.trim());
  const rest = titleIndex === -1 ? '' : lines.slice(titleIndex + 1).join(' ').trim();
  return rest || 'No additional text';
}

function formatTime(value) {
  const date = new Date(value);
  const pad = (number) => String(number).padStart(2, '0');
  return `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())} ${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}`;
}

function escapeHtml(value) {
  return value.replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
}

async function request(url, options = {}) {
  const response = await fetch(url, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  if (!response.ok) {
    throw new Error('Request failed');
  }
  if (response.status === 204) {
    return null;
  }
  return response.json();
}

async function loadNotes() {
  state.notes = await request('/api/notes');
}

async function saveCurrentNote() {
  if (!state.currentNote || state.saving || state.currentNote.body === state.draft) {
    return;
  }
  state.saving = true;
  try {
    const saved = await request(`/api/notes/${state.currentNote.id}`, {
      method: 'PUT',
      body: JSON.stringify({ body: state.draft }),
    });
    state.currentNote = saved;
    state.draft = saved.body;
    const index = state.notes.findIndex((note) => note.id === saved.id);
    if (index >= 0) {
      state.notes[index] = saved;
    } else {
      state.notes.unshift(saved);
    }
    state.notes.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  } finally {
    state.saving = false;
  }
}

function setRoute(path) {
  history.pushState(null, '', path);
  render();
}

async function openNote(id) {
  await saveCurrentNote();
  const note = await request(`/api/notes/${id}`);
  state.currentNote = note;
  state.draft = note.body;
  setRoute(`/notes/${note.id}`);
}

async function createNote() {
  await saveCurrentNote();
  const note = await request('/api/notes', { method: 'POST' });
  state.notes.unshift(note);
  state.currentNote = note;
  state.draft = note.body;
  setRoute(`/notes/${note.id}`);
  setTimeout(() => document.querySelector('[data-testid="input-note-body"]')?.focus(), 0);
}

async function deleteNote(id, fromEditor = false) {
  if (!confirm('Permanently delete this note? This action cannot be undone.')) {
    return;
  }
  await request(`/api/notes/${id}`, { method: 'DELETE' });
  state.notes = state.notes.filter((note) => note.id !== id);
  if (fromEditor || state.currentNote?.id === id) {
    state.currentNote = null;
    state.draft = '';
    setRoute('/');
  } else {
    render();
  }
}

function renderGate() {
  app.innerHTML = `
    <main class="gate-wrap">
      <section class="gate-card" data-testid="card-password-gate">
        <h1 data-testid="text-app-title">Private Notes</h1>
        <p data-testid="text-gate-description">Unlock this tab session to view your notes.</p>
        <form class="gate-form" data-testid="form-unlock">
          <input data-testid="input-password" type="password" autocomplete="current-password" placeholder="Password" autofocus />
          <button class="primary" data-testid="button-unlock" type="submit">Unlock notes</button>
          <div class="error" data-testid="text-password-error">${escapeHtml(state.error)}</div>
        </form>
      </section>
    </main>
  `;
  app.querySelector('form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const password = app.querySelector('input').value;
    if (!password) {
      state.error = 'Password is required';
      renderGate();
      return;
    }
    if (password !== PASSWORD) {
      state.error = 'Incorrect password';
      renderGate();
      return;
    }
    state.error = '';
    state.unlocked = true;
    await loadNotes();
    render();
  });
}

function shell(content) {
  app.innerHTML = `<main class="shell">${content}</main>`;
}

function renderList() {
  state.currentNote = null;
  const query = state.query.trim().toLowerCase();
  const filtered = state.notes.filter((note) => {
    const title = titleFor(note.body).toLowerCase();
    return !query || title.includes(query) || note.body.toLowerCase().includes(query);
  });
  const rows = filtered.map((note) => `
    <article class="note-row" data-testid="row-note-${note.id}">
      <button class="note-main" data-testid="button-open-note-${note.id}" type="button" data-open-id="${note.id}">
        <h2 class="note-title" data-testid="text-note-title-${note.id}">${escapeHtml(titleFor(note.body))}</h2>
        <div class="note-preview" data-testid="text-note-preview-${note.id}">${escapeHtml(previewFor(note.body))}</div>
      </button>
      <div class="row-actions">
        <time class="timestamp" data-testid="text-note-timestamp-${note.id}">${formatTime(note.updatedAt)}</time>
        <button class="icon-danger" data-testid="button-delete-note-${note.id}" type="button" data-delete-id="${note.id}" aria-label="Delete note">Delete</button>
      </div>
    </article>
  `).join('');
  shell(`
    <header class="topbar">
      <div class="brand">
        <h1 data-testid="text-notes-heading">Notes</h1>
        <p data-testid="text-notes-count">${filtered.length} ${filtered.length === 1 ? 'note' : 'notes'}</p>
      </div>
      <button class="primary" data-testid="button-new-note" type="button">New Note</button>
    </header>
    <section class="list-card" data-testid="section-notes-list">
      <div class="search-wrap">
        <input data-testid="input-search" type="search" placeholder="Search notes" value="${escapeHtml(state.query)}" />
      </div>
      ${rows ? `<div class="notes-list">${rows}</div>` : `<div class="empty" data-testid="status-empty-notes"><div><h2 data-testid="text-empty-title">No notes found</h2><p data-testid="text-empty-description">Create a new note or adjust your search.</p></div></div>`}
    </section>
  `);
  app.querySelector('[data-testid="button-new-note"]').addEventListener('click', createNote);
  app.querySelector('[data-testid="input-search"]').addEventListener('input', (event) => {
    state.query = event.target.value;
    renderList();
    const input = app.querySelector('[data-testid="input-search"]');
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
  });
  app.querySelectorAll('[data-open-id]').forEach((button) => button.addEventListener('click', () => openNote(button.dataset.openId)));
  app.querySelectorAll('[data-delete-id]').forEach((button) => button.addEventListener('click', () => deleteNote(button.dataset.deleteId)));
}

function renderEditor() {
  const note = state.currentNote;
  shell(`
    <header class="topbar">
      <div class="brand">
        <h1 data-testid="text-editor-title">${escapeHtml(titleFor(state.draft))}</h1>
        <p data-testid="text-editor-timestamp">Last edited ${formatTime(note.updatedAt)}</p>
      </div>
      <div class="editor-actions">
        <button class="secondary" data-testid="button-back-list" type="button">Back to list</button>
        <button class="danger" data-testid="button-delete-current-note" type="button">Delete</button>
      </div>
    </header>
    <section class="editor-card" data-testid="section-note-editor">
      <textarea data-testid="input-note-body" placeholder="Start typing...">${escapeHtml(state.draft)}</textarea>
    </section>
  `);
  const textarea = app.querySelector('[data-testid="input-note-body"]');
  textarea.addEventListener('input', (event) => {
    state.draft = event.target.value;
  });
  app.querySelector('[data-testid="button-back-list"]').addEventListener('click', async () => {
    await saveCurrentNote();
    await loadNotes();
    setRoute('/');
  });
  app.querySelector('[data-testid="button-delete-current-note"]').addEventListener('click', () => deleteNote(note.id, true));
  setTimeout(() => textarea.focus(), 0);
}

async function render() {
  if (!state.unlocked) {
    renderGate();
    return;
  }
  const match = location.pathname.match(/^\/notes\/([^/]+)$/);
  if (match) {
    if (!state.currentNote || state.currentNote.id !== match[1]) {
      try {
        state.currentNote = await request(`/api/notes/${match[1]}`);
        state.draft = state.currentNote.body;
      } catch (error) {
        setRoute('/');
        return;
      }
    }
    renderEditor();
    return;
  }
  await saveCurrentNote();
  renderList();
}

window.addEventListener('popstate', async () => {
  await saveCurrentNote();
  render();
});

window.addEventListener('beforeunload', (event) => {
  if (state.currentNote && state.currentNote.body !== state.draft) {
    navigator.sendBeacon(`/api/notes/${state.currentNote.id}`, new Blob([JSON.stringify({ body: state.draft })], { type: 'application/json' }));
  }
});

render();
"}

